import ast
from pathlib import Path

SAFETY_PATHS = {"__init__.py", "cli.py", "app.py", "main.py", "api.py", "server.py", "config.py"}


def _surface(tree):
    result = {}
    for node in tree.body:
        if isinstance(node, ast.ClassDef):
            if not node.name.startswith("_"):
                result[node.name] = node
                for item in node.body:
                    if isinstance(item, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        if item.name == "__init__" or not item.name.startswith("_"):
                            result[f"{node.name}.{item.name}"] = item
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if not node.name.startswith("_"):
                result[node.name] = node
    return result


def _kwonly_required(fn):
    pos = fn.args.posonlyargs + fn.args.args
    defaults = fn.args.defaults
    required_pos = len(pos) - len(defaults)
    required = set()
    for i, arg in enumerate(pos):
        if i >= required_pos:
            required.add(arg.arg)
    for arg, default in zip(fn.args.kwonlyargs, fn.args.kw_defaults):
        if default is None:
            required.add(arg.arg)
    return required


def _descriptor(fn):
    for dec in fn.decorator_list:
        name = None
        if isinstance(dec, ast.Name):
            name = dec.id
        elif isinstance(dec, ast.Attribute):
            name = dec.attr
        if name in ("property", "classmethod", "staticmethod"):
            return name
    return None


def _compatible(old, new):
    if not isinstance(old, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return True
    if not isinstance(new, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return False
    if isinstance(old, ast.AsyncFunctionDef) != isinstance(new, ast.AsyncFunctionDef):
        return False
    if _descriptor(old) != _descriptor(new):
        return False

    old_pos = old.args.posonlyargs + old.args.args
    new_pos = new.args.posonlyargs + new.args.args
    old_posonly = len(old.args.posonlyargs)
    new_posonly = len(new.args.posonlyargs)

    if len(new_pos) < len(old_pos) and not new.args.vararg:
        return False

    for i, oarg in enumerate(old_pos):
        if i >= len(new_pos):
            if not new.args.vararg:
                return False
            continue
        narg = new_pos[i]
        old_kw_capable = i >= old_posonly
        new_kw_capable = i >= new_posonly
        if old_kw_capable:
            if not new_kw_capable:
                return False
            if narg.arg != oarg.arg:
                return False

    new_kw_names = {a.arg for a in new.args.kwonlyargs}
    if new.args.kwarg is not None:
        new_kw_names = None

    old_required = _kwonly_required(old)
    new_required = _kwonly_required(new)
    old_defaults = {a.arg for i, a in enumerate(old_pos)
                    if i >= len(old_pos) - len(old.args.defaults)}
    new_defaults = {a.arg for i, a in enumerate(new_pos)
                    if i >= len(new_pos) - len(new.args.defaults)}

    for oarg in old_pos:
        if oarg.arg in old_required:
            continue
        if oarg.arg not in {a.arg for a in new_pos}:
            if new_kw_names is not None and oarg.arg not in new_kw_names:
                return False

    for i, oarg in enumerate(old_pos):
        if i >= old_posonly:
            if oarg.arg in old_defaults and i < len(new_pos):
                if new_pos[i].arg not in new_defaults and new_pos[i].arg not in new.args.kwonlyargs:
                    return False

    for arg in new.args.kwonlyargs:
        if arg.arg in new_required and arg.arg not in old_required:
            return False

    for name in old_required:
        if name in {a.arg for a in old.args.kwonlyargs}:
            if name not in new_required and name not in new_kw_names:
                return False

    if old.args.vararg is not None and new.args.vararg is None:
        return False
    if old.args.kwarg is not None and new.args.kwarg is None:
        return False

    return True


def api_incompatibilities(before: str, after: str) -> list[str]:
    try:
        old_tree = ast.parse(before)
    except SyntaxError as exc:
        return [f"before source has SyntaxError: {exc}"]
    try:
        new_tree = ast.parse(after)
    except SyntaxError as exc:
        return [f"after source has SyntaxError: {exc}"]

    old_surface = _surface(old_tree)
    new_surface = _surface(new_tree)
    problems = []

    for name, old_node in old_surface.items():
        if name not in new_surface:
            kind = "class" if isinstance(old_node, ast.ClassDef) else "function"
            problems.append(f"public {kind} '{name}' was removed")
            continue
        new_node = new_surface[name]
        old_is_class = isinstance(old_node, ast.ClassDef)
        new_is_class = isinstance(new_node, ast.ClassDef)
        if old_is_class != new_is_class:
            problems.append(f"public name '{name}' changed kind")
            continue
        if not old_is_class:
            if not _compatible(old_node, new_node):
                problems.append(f"public function '{name}' has an incompatible signature change")

    return problems


def check_public_api(root: Path, changed: list[str], base_ref: str | None, failures: list[str]) -> None:
    ref = base_ref or "HEAD"
    for path in changed:
        if path not in SAFETY_PATHS and not path.endswith(".py"):
            continue
        target = Path(path)
        if not target.is_absolute():
            target = root / path
        try:
            base_text = read_base_text(root, ref, path)
        except RuntimeError as exc:
            failures.append(f"{path}: could not read base version ({exc})")
            continue
        if base_text is None:
            continue
        if not target.exists():
            failures.append(f"{path}: public API file was removed")
            continue
        try:
            current_text = target.read_text()
        except OSError as exc:
            failures.append(f"{path}: could not read current file ({exc})")
            continue
        for problem in api_incompatibilities(base_text, current_text):
            failures.append(f"{path}: {problem}")
